articles.description:
html.content-warning-locked {
 overflow: hidden;
 }

 html:has(#content-warning-accepted:not(:target) + .content-warning-overlay) {
 overflow: hidden;
 }

 .content-warning-close-target {
 position: fixed;
 width: 1px;
 height: 1px;
 opacity: 0;
 pointer-events: none;
 }

 #content-warning-accepted:target + .content-warning-overlay {
 display: none;
 }

 .content-warning-overlay {
 position: fixed;
 inset: 0;
 z-index: 1000;
 display: grid;
 place-items: center;
 padding: 1.25rem;
 background: rgba(0, 0, 0, 0.68);
 color: #333333;
 overflow: auto;
 }

 .content-warning-dialog {
 width: min(92vw, 520px);
 padding: 1.35rem 1.25rem 1.25rem;
 text-align: center;
 background:
 linear-gradient(180deg, #ffffff 0%, #eeeeee 48%, #d8d8d8 49%, #f3f3f3 100%);
 border: 1px solid #9f9f9f;
 border-radius: 10px;
 box-shadow:
 inset 0 1px 0 #ffffff,
 inset 0 -1px 0 #c3c3c3,
 0 12px 28px #050505;
 text-shadow: 0 1px 0 #ffffff;
 }

 .content-warning-icon {
 display: block;
 width: 170px;
 max-width: 56vw;
 height: auto;
 margin: 0 auto 1rem;
 }

 .content-warning-title {
 margin: 0 0 0.7rem;
 font-size: 1.35rem;
 line-height: 1.3;
 font-weight: 800;
 }

 .content-warning-description {
 margin: 0 auto 1.15rem;
 max-width: 32rem;
 line-height: 1.7;
 }

 .content-warning-actions {
 display: flex;
 flex-wrap: wrap;
 justify-content: center;
 gap: 0.75rem;
 }

 .content-warning-actions button,
 .content-warning-actions a,
 .content-warning-actions label {
 display: inline-block;
 min-width: 7rem;
 padding: 0.45rem 1rem;
 color: inherit;
 text-decoration: none;
 cursor: pointer;
 }

 html.dark .content-warning-overlay {
 color: #f2f2f2;
 }

 html.dark .content-warning-dialog {
 background:
 linear-gradient(180deg, #555555 0%, #373737 48%, #1f1f1f 49%, #343434 100%);
 border-color: #050505;
 box-shadow:
 inset 0 1px 0 #6a6a6a,
 inset 0 -1px 0 #000000,
 0 12px 28px #000000;
 text-shadow: 0 -1px 0 #000000;
 }








